using Microsoft.AspNetCore.HttpOverrides;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// Fix: Scoped IUserService cannot be resolved from root provider (ValidateScopes is
// now enabled in development). Register CacheService as scoped, or use IServiceScopeFactory.
builder.Services.AddScoped<ICacheService, CacheService>();
// Fix: HttpClientFactory now uses SocketsHttpHandler by default; cast to HttpClientHandler
// throws InvalidCastException. Use ConfigurePrimaryHttpMessageHandler instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });
// Fix: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers from proxies not in
// KnownProxies or KnownNetworks. Add your reverse proxy address here.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: Replace with your actual proxy IP address(es)
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});
// Fix: HttpClientFactory now redacts all header values in Trace-level logs by default.
// Allowlist the specific non-sensitive headers you need to debug.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" &&
        h != "X-Correlation-Id" &&
        h != "Accept" &&
        h != "Content-Type"));
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

